test("inherited grants resolve through parent chains (ACCESS-284)",()=>{
  const dir={"report-reader":{grants:["report:download"]},auditor:{grants:[],parent:"report-reader"},deep:{grants:[],parent:"auditor"}};
  assert.equal(downloadReport({id:"u",roles:["auditor"],denied:[]},"r1",dir,reports).status,200);
  assert.equal(downloadReport({id:"u",roles:["deep"],denied:[]},"r1",dir,reports).status,200);
});
test("parent cycles and missing parents terminate without granting",()=>{
  const dir={a:{grants:[],parent:"b"},b:{grants:[],parent:"a"},orphan:{grants:[],parent:"gone"}};
  assert.equal(allows({id:"u",roles:["a"],denied:[]},"report:download",dir),false);
  assert.equal(allows({id:"u",roles:["orphan"],denied:[]},"report:download",dir),false);
});
test("explicit denial applies to analysts too",()=>{
  assert.equal(downloadReport({id:"u",roles:["analyst"],denied:["report:download"]},"r1",directory,reports).status,403);
});
EOF
